			function checkValidate() {
			    var dmSrvyDtl = app.lookup("dmSrvyDtl");
			    
			    if (dmSrvyDtl.getValue("QUSTNB_NM") == "" || dmSrvyDtl.getValue("QUSTNB_NM") == null) {
			        console.log("1");
			        return true; 
			    }
			    if (dmSrvyDtl.getValue("SRVY_PURPS_CN") == "" || dmSrvyDtl.getValue("SRVY_PURPS_CN") == null) {
			        console.log("2");
			        return true; 
			    }
			    if (dmSrvyDtl.getValue("SRVY_WRT_GUIDAN_CN") == "" || dmSrvyDtl.getValue("SRVY_WRT_GUIDAN_CN") == null) {
			        console.log("3");
			        return true; 
			    }
			    if (dmSrvyDtl.getValue("SRVY_BGNG_YMD") == "" || dmSrvyDtl.getValue("SRVY_BGNG_YMD") == null) {
			        console.log("4");
			        return true; 
			    }
			    if (dmSrvyDtl.getValue("SRVY_END_YMD") == "" || dmSrvyDtl.getValue("SRVY_END_YMD") == null) {
			        console.log("5");
			        return true; 
			    }
			    if (dmSrvyDtl.getValue("TRPR_INFO_NO") == "__" || dmSrvyDtl.getValue("TRPR_INFO_NO") == null) {
			        console.log("6");
			        return true; 
			    }
			    
			    return false;
			}

			/*
			 * "설문시작" 버튼(btnAdd3)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnAdd3Click(e){
			    var btnAdd3 = e.control;
			    var grd = app.lookup("grd1");
			    var dmSrvyDtl = app.lookup("dmSrvyDtl");
			    var dsGrdngRelmList = app.lookup("dsGrdngRelmList");
			    var dsResultCrtrList = app.lookup("dsResultCrtrList");
			    
			    // 설문 시작 전제 조건 
			    // 채점영역, 채점기준, 설문정보. 설문대상 선택. 설문기간내에 들어와야 함.
			    if (null == dmSrvyDtl.getValue("QUSTNB_MNG_NO")) {
			        util.Msg.alert(app, "설문 문항을 등록해주세요.");
			        return;
			    }
			    if(checkValidate()){
			        util.Msg.alert(app, "설문지 정보를 입력해주세요.");
			        return;
			    }
			    if (grd.getRowCount() == 0) {
			        util.Msg.alert(app, "설문 문항을 등록해주세요.");
			        return;
			    }
			    if (dsGrdngRelmList.getRowCount() == 0) {
			        util.Msg.alert(app, "채점영역 을 등록해주세요.");
			        return;
			    }
			    if (dsResultCrtrList.getRowCount() == 0) {
			        util.Msg.alert(app, "채점기준을 등록해주세요.");
			        return;
			    }
			    
			    util.Msg.confirm(app, "설문시작 상태로 변경하시겠습니까?\n대상자 설문 참여시 수정 및 중지가 불가능 합니다.", null, function() {
			        dmSrvyDtl.setValue("TYPE", "START");
			        util.Submit.send(app, "subStatus", function(pbSuccess) {
			            if (pbSuccess) {
			                // 채점영역, 채점기준, 설문정보. 설문대상 선택. 설문기간내에 들어와야 함.
			                returnCheck();
			                // app.lookup("grpSearch").redraw();
			            }
			        });
			    });    
			     
			}

			function returnCheck() {
			    var dmReturn = app.lookup("dmReturn");
			    var dmSrvyDtl = app.lookup("dmSrvyDtl");
			    
			    var result = dmReturn.getValue("RETURN_TYPE");
			    var type = dmSrvyDtl.getValue("TYPE");
			    
			    
			    // RESULT_TYPE 01: PASS 02: 종료일자 이슈 , 03: 응답 여부.
			    if ("02" == result) {
			        util.Msg.alert(app, "설문 종료일자가 오늘보다 이릅니다.\n 변경 후 시도해주십시오.");
			    } else if ("03" == result) {
			        util.Msg.alert(app, "해당 설문에 대한 참여가 확인 되었습니다.\n참여자가 있는 설문은 중지 할 수 없습니다. \n 관리자에게 문의 바랍니다.");
			    } else {
			        if ("START" == type) {
			            util.Msg.alert(app, "설문이 시작 되었습니다.\n 대상자에게 안내 해주세요.");
			        }else {
			            util.Msg.alert(app, "설문이 중지 되었습니다.");
			        }
			        doList();
			    }
			}

